#include <iostream>
#include <string>
#include <cmath>
using namespace std;

int main() {
    string input;
    cin >> input;
    long long n = stoll(input.substr(0, input.size() - 1));
    char s = input.back();

    long long seat_order;
    if (s == 'f') seat_order = 1;
    else if (s == 'e') seat_order = 2;
    else if (s == 'd') seat_order = 3;
    else if (s == 'a') seat_order = 4;
    else if (s == 'b') seat_order = 5;
    else if (s == 'c') seat_order = 6;

    long long total_time = 0;

    if (n == 1) {
        total_time = seat_order;
    } else {
        long long current_row = 1;
        long long step_size = 2;
        long long prev_row = 0;

        while (true) {
            long long next_row = current_row + step_size;
            if (current_row <= n && n < next_row) {
                break;
            }
            prev_row = current_row;
            current_row = next_row;
            step_size = (step_size == 2) ? 1 : 2;
        }

        long long rows_served = current_row - prev_row;
        long long groups = (rows_served + 1) / 2;
        total_time = groups * 12;

        long long move_time = current_row - 1;
        total_time += move_time;

        long long offset = n - current_row;
        if (offset % 2 == 0) {
            total_time += (offset / 2) * 12;
        } else {
            total_time += (offset / 2) * 12 + 6;
        }

        total_time += seat_order;
    }

    cout << total_time << endl;
    return 0;
}
